    #[test]
    fn receipt_version_pins_label_or_legacy_lungs_directory() {
        let uuid = "00000000-0000-4000-8000-000000000001";
        let legacy = serde_json::json!({"version":1});
        assert_eq!(lungs_directory_name(&legacy, "ID-1", uuid).unwrap(), uuid);
        let labelled = serde_json::json!({"version":2,"container_label":"ID_1"});
        assert_eq!(lungs_directory_name(&labelled, "ID-1", uuid).unwrap(), "ID_1");
        assert!(lungs_directory_name(&labelled, "ID-2", uuid).is_err());
        assert!(lungs_directory_name(&labelled, "ID-01", uuid).is_err());
        assert!(lungs_directory_name(&labelled, "3tchedCtlChatbot", uuid).is_err());
        assert!(lungs_directory_name(&serde_json::json!({"version":2}), "ID-1", uuid).is_err());
        assert!(lungs_directory_name(&serde_json::json!({"version":3}), "ID-1", uuid).is_err());
